command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$branch="work/outbound-storage-drag-20261006"
$main="4f03ea8bc499cd8e4d064431753d4f7aefac0fff"
$accepted="0d23048d47b158b98c2aff0cf7f3ec5ffc8c5ebb"
$candidate="8d7f9aa0b42c654a0f922ccf317a1afc5b649d0d"
$temp=Join-Path $env:RUNNER_TEMP ("same-app-drag-regression-"+$env:GITHUB_RUN_ID)
$worktreeAdded=$false
try {
  Set-Location -LiteralPath $repo
  & git fetch origin main $branch --no-tags --prune
  if($LASTEXITCODE -ne 0){throw "candidate fetch failed"}
  $mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
  $branchSha=(& git rev-parse ("refs/remotes/origin/"+$branch)).Trim()
  if($mainSha -ne $main){throw "main moved before same-app regression validation: $mainSha"}
  if($branchSha -ne $candidate){throw "candidate moved before same-app regression validation: $branchSha"}

  & git diff --quiet $accepted $candidate -- app src
  if($LASTEXITCODE -ne 0){throw "P2 product code changed after #464 outbound acceptance"}

  & git worktree add --detach $temp $candidate
  if($LASTEXITCODE -ne 0){throw "candidate worktree creation failed"}
  $worktreeAdded=$true
  Set-Location -LiteralPath $temp
  $env:PYTHONIOENCODING="utf-8"

  & git diff --check $main $candidate
  if($LASTEXITCODE -ne 0){throw "git diff --check failed"}

  & python -X utf8 tools\winui\check_python_static.py tests\winui\test_same_app_drag_regression_gui.py
  if($LASTEXITCODE -ne 0){throw "same-app drag GUI static check failed"}

  & python -X utf8 tools\winui\run_checks.py fast --before $accepted --head $candidate
  if($LASTEXITCODE -ne 0){throw "same-app drag regression FAST failed"}

  & .\build.bat Release
  if($LASTEXITCODE -ne 0){throw "same-app regression Release build failed"}

  & python -X utf8 tools\winui\check_python_deps.py --gui
  if($LASTEXITCODE -ne 0){throw "GUI dependency check failed"}

  $env:FLY_MIGRATION_CONFIGURATION="Release"
  & python -X utf8 -u tests\winui\test_same_app_drag_regression_gui.py
  if($LASTEXITCODE -ne 0){throw "focused same-app physical drag regression failed"}

  Write-Host ("OUTBOUND_DRAG_REVIEWED_PRODUCT="+$accepted)
  Write-Host ("SAME_APP_DRAG_REGRESSION_CANDIDATE="+$candidate)
  Write-Host "SAME_APP_DRAG_REGRESSION_ACCEPTANCE=PASS"
} finally {
  Set-Location -LiteralPath $repo
  if($worktreeAdded){
    & git worktree remove --force $temp 2>$null
    & git worktree prune
  } elseif(Test-Path -LiteralPath $temp) {
    Remove-Item -LiteralPath $temp -Recurse -Force -ErrorAction SilentlyContinue
  }
}
